const ICONS = {"180": "", "192": "", "512": ""};
const MANIFEST = JSON.stringify({name:'ريفاد RIFAD - إدارة المخلفات الخطرة',short_name:'ريفاد RIFAD',lang:'ar',dir:'rtl',start_url:'/',scope:'/',display:'standalone',background_color:'#f3f5f4',theme_color:'#0f6e52',icons:[{src:'/icon-192.png',sizes:'192x192',type:'image/png',purpose:'any maskable'},{src:'/icon-512.png',sizes:'512x512',type:'image/png',purpose:'any maskable'}]});
const SW = "const C='haz-v2';self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(C).then(c=>c.add('/')).catch(()=>{}))});self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.pathname.startsWith('/api/'))return;e.respondWith(fetch(e.request).then(r=>{const k=r.clone();caches.open(C).then(c=>c.put(e.request,k));return r}).catch(()=>caches.match(e.request).then(m=>m||caches.match('/'))))});";
module.exports = function (p, res) {
  const png = { '/icon-192.png':192, '/icon-512.png':512, '/apple-touch-icon.png':180 }[p];
  if (png) { res.writeHead(200, {'Content-Type':'image/png','Cache-Control':'public, max-age=86400'}); res.end(Buffer.from(ICONS[png], 'base64')); return true; }
  if (p === '/manifest.webmanifest') { res.writeHead(200, {'Content-Type':'application/manifest+json'}); res.end(MANIFEST); return true; }
  if (p === '/sw.js') { res.writeHead(200, {'Content-Type':'text/javascript','Service-Worker-Allowed':'/','Cache-Control':'no-cache'}); res.end(SW); return true; }
  return false;
};
